mapper.select:
SELECT fu.*, GROUP_CONCAT(distinct ug.group_name) AS userGroups, GROUP_CONCAT(distinct NULLIF(rrr.role_id, '')) AS roles, GROUP_CONCAT(DISTINCT nullif(CONCAT_WS('', rrr.storage_privilege, rrr.repository_privilege, rrr.path_privilege), '')) AS authorities
FROM folib_user fu LEFT JOIN (
SELECT rrr1.role_id, rrr1.storage_privilege, rrr1.repository_privilege, rrr1.path_privilege, rrr1.entity_id AS user_id FROM role_resource_ref rrr1 WHERE rrr1.ref_type = 1 UNION all SELECT rrr2.role_id, rrr2.storage_privilege, rrr2.repository_privilege, rrr2.path_privilege, ugr.user_id AS user_id FROM user_group_ref ugr JOIN role_resource_ref rrr2 ON ugr.user_group_id = rrr2.entity_id WHERE rrr2.ref_type = 2
SELECT rrr1.role_id, rrr1.storage_privilege, rrr1.repository_privilege, rrr1.path_privilege, rrr1.entity_id AS user_id FROM role_resource_ref rrr1 WHERE rrr1.ref_type = 1
SELECT rrr1.role_id, rrr1.storage_privilege, rrr1.repository_privilege, rrr1.path_privilege, rrr1.entity_id AS user_id FROM role_resource_ref rrr1 WHERE rrr1.ref_type = 1
) rrr ON fu.id = rrr.user_id left join user_group_ref ugr on fu.id = ugr.user_id left join user_group ug on ug.id = ugr.user_group_id
and id = #{user.id}
and username like concat('%',#{user.username},'%')
and password = #{user.password}
and original_password = #{user.originalPassword}
and avatar = #{user.avatar}
and email like concat('%',#{user.email},'%')
and user_type = #{user.userType}
and enabled = #{user.enabled}
and source_id = #{user.sourceId}
group by fu.id limit #{pageable.pageNumber}, #{pageable.pageSize}

