SELECT fu.*, GROUP_CONCAT(distinct ug.id) AS userGroupIds, GROUP_CONCAT(distinct ug.group_name) AS userGroups, GROUP_CONCAT(distinct rrr.role_id) AS roles, GROUP_CONCAT(DISTINCT CONCAT_WS('', rrr.storage_privilege, rrr.repository_privilege, rrr.path_privilege)) AS authorities FROM folib_user fu LEFT JOIN (
SELECT rrr1.role_id, rrr1.storage_privilege, rrr1.repository_privilege, rrr1.path_privilege, rrr1.entity_id AS user_id FROM role_resource_ref rrr1 WHERE rrr1.ref_type = 1 UNION all SELECT rrr2.role_id, rrr2.storage_privilege, rrr2.repository_privilege, rrr2.path_privilege, ugr.user_id AS user_id FROM user_group_ref ugr JOIN role_resource_ref rrr2 ON ugr.user_group_id = rrr2.entity_id WHERE rrr2.ref_type = 2
SELECT rrr1.role_id, rrr1.storage_privilege, rrr1.repository_privilege, rrr1.path_privilege, rrr1.entity_id AS user_id FROM role_resource_ref rrr1 WHERE rrr1.ref_type = 1
SELECT rrr1.role_id, rrr1.storage_privilege, rrr1.repository_privilege, rrr1.path_privilege, rrr1.entity_id AS user_id FROM role_resource_ref rrr1 WHERE rrr1.ref_type = 1
) rrr ON fu.id = rrr.user_id left join user_group_ref ugr on fu.id = ugr.user_id left join user_group ug on ug.id = ugr.user_group_id
and fu.id = #{id}
and username concat('%', #{username}, '%')
and password = #{password}
and original_password = #{originalPassword}
and avatar = #{avatar}
and email = #{email}
and user_type = #{userType}
and enabled = #{enabled}
and source_id = #{sourceId}
group by fu.id

SELECT fu.*, rrr.id , rrr.storage_id, rrr.repository_id, rrr.`path`, GROUP_CONCAT(distinct ug.id) AS userGroupIds, GROUP_CONCAT(distinct ug.group_name) AS userGroups, GROUP_CONCAT(distinct rrr.role_id) AS roles, GROUP_CONCAT(DISTINCT CONCAT_WS('', rrr.storage_privilege)) AS storagePrivilege, GROUP_CONCAT(DISTINCT CONCAT_WS('', rrr.repository_privilege)) AS repositoryPrivilege, GROUP_CONCAT(DISTINCT CONCAT_WS('', rrr.path_privilege)) AS pathPrivilege, GROUP_CONCAT(DISTINCT CONCAT_WS('', rrr.storage_privilege, rrr.repository_privilege, rrr.path_privilege)) AS authorities FROM folib_user fu LEFT JOIN (
SELECT rrr1.role_id, rrr1.storage_privilege, rrr1.repository_privilege, rrr1.path_privilege, rrr1.entity_id AS user_id, r.id , r.storage_id, r.repository_id, r.`path` FROM role_resource_ref rrr1 left join resource r on r.id = rrr1.resource_id WHERE rrr1.ref_type = 1 UNION all SELECT rrr2.role_id, rrr2.storage_privilege, rrr2.repository_privilege, rrr2.path_privilege, ugr.user_id AS user_id, r.id , r.storage_id, r.repository_id, r.`path` FROM user_group_ref ugr JOIN role_resource_ref rrr2 ON ugr.user_group_id = rrr2.entity_id left join resource r on r.id = rrr2.resource_id WHERE rrr2.ref_type = 2
SELECT rrr1.role_id, rrr1.storage_privilege, rrr1.repository_privilege, rrr1.path_privilege, rrr1.entity_id AS user_id, r.id , r.storage_id, r.repository_id, r.`path` FROM role_resource_ref rrr1 join resource r on r.id = rrr1.resource_id WHERE rrr1.ref_type = 1
SELECT rrr1.role_id, rrr1.storage_privilege, rrr1.repository_privilege, rrr1.path_privilege, rrr1.entity_id AS user_id, r.id , r.storage_id, r.repository_id, r.`path` FROM role_resource_ref rrr1 join resource r on r.id = rrr1.resource_id WHERE rrr1.ref_type = 1
) rrr ON fu.id = rrr.user_id left join user_group_ref ugr on fu.id = ugr.user_id left join user_group ug on ug.id = ugr.user_group_id
and rrr.storage_id = #{storageId}
and rrr.repository_id = #{repositoryId}
and rrr.path = #{path}
and fu.username in
#{username}
group by fu.id,rrr.id
